"""Dependency-free, printable experiment report with accessible SVG charts."""
from pathlib import Path
import json,html
def render(root):
 r=json.loads((root/'reports/metrics.json').read_text(encoding='utf-8')); e=html.escape
 selected=r['selected_model']; score=r['models'][selected]['test']; title=r['project']; sentiment=title=='ReviewPulse'; accent='#a14a38' if sentiment else '#286b57'
 modelrows=''.join('<tr><td>'+e(name)+(' <small>SELECTED</small>' if name==selected else '')+'</td>'+''.join(f'<td>{m["test"][key]:.4f}</td>' for key in ['accuracy','macro_f1','pr_auc' if sentiment else 'top3_accuracy'])+'</tr>' for name,m in r['models'].items())
 bars=''
 for i,(name,m) in enumerate(r['models'].items()):
  y=45+i*80; width=m['test']['macro_f1']*560
  bars+=f'<text x="0" y="{y-10}" font-size="13">{name}</text><rect x="0" y="{y}" width="560" height="18" fill="#e7ece4"/><rect x="0" y="{y}" width="{width}" height="18" fill="{accent}"/><text x="580" y="{y+14}" font-size="14">{m["test"]["macro_f1"]:.3f}</text>'
 # Full matrix with per-cell titles. Axis labels listed separately for 77-class model.
 cm=r['confusion_matrix']; n=len(cm); size=500/n; vmax=max(max(row) for row in cm); cells=''
 for i,row in enumerate(cm):
  for j,v in enumerate(row):
   cells+=f'<rect x="{j*size:.3f}" y="{i*size:.3f}" width="{size:.3f}" height="{size:.3f}" fill="{accent}" opacity="{.03+.97*v/max(vmax,1):.3f}"><title>True {e(r["classes"][i])}; predicted {e(r["classes"][j])}: {v}</title></rect>'
   if n==2: cells+=f'<text x="{j*size+size/2}" y="{i*size+size/2}" text-anchor="middle" fill="{chr(35)+"fff" if v>vmax/2 else chr(35)+"243737"}" font-size="30">{v}</text>'
 errors=''.join(f'<tr><td>{e(x["text"])}</td><td>{e(x["actual"])}</td><td>{e(x["predicted"])}</td></tr>' for x in r['errors'][:12])
 polish=''.join(f'<tr><td>{e(k)}</td><td>{v["accuracy"]:.4f}</td><td>{v["macro_f1"]:.4f}</td></tr>' for k,v in r['polish_control']['models'].items())
 perclass=''.join(f'<tr><td>{e(k)}</td><td>{v["precision"]:.3f}</td><td>{v["recall"]:.3f}</td><td>{v["f1-score"]:.3f}</td><td>{int(v["support"])}</td></tr>' for k,v in r['classification_report'].items() if k in r['classes'])
 domain=''
 if 'domain_transfer' in r: domain='<h2>04 / Domain transfer · Transfer między domenami</h2><p>Separate embedding logistic regression fitted on other-domain training rows, evaluated on target-domain test rows. Not the production classifier.</p><pre>'+e(json.dumps(r['domain_transfer'],indent=2))+'</pre>'
 training=r['training']
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — experiment report</title><style>
body{{font:14px/1.65 "Segoe UI",sans-serif;color:#283a33;background:#f7f7f2;max-width:1000px;margin:0 auto;padding:60px 35px}}h1{{font-size:62px;letter-spacing:-3px;line-height:1.05;margin:20px 0}}h2{{font-size:23px;margin-top:50px;letter-spacing:-.5px}}.eyebrow{{color:{accent};font-size:11px;letter-spacing:2px}}.lede{{max-width:700px;color:#72816f}}.stats{{display:flex;gap:50px;border-block:1px solid #d5decf;padding:25px 0;margin:32px 0}}.stats b{{display:block;font-size:35px;color:{accent};font-weight:400}}.stats span{{font-size:11px}}table{{border-collapse:collapse;width:100%;font-size:12px;margin:22px 0;background:white}}td,th{{text-align:left;padding:13px;border-bottom:1px solid #e4e9df;vertical-align:top}}th{{background:#edf1e8;font-weight:500}}small{{font-size:8px;color:{accent}}}svg{{max-width:100%;height:auto}}.matrix{{max-width:500px;border:1px solid #d5decf}}.note{{background:#edf1e8;padding:20px;border-left:3px solid {accent}}}pre{{white-space:pre-wrap;font-size:12px}}details{{margin:20px 0}}footer{{border-top:1px solid #d5decf;margin-top:45px;padding-top:20px;color:#7c8875;font-size:11px}}@media print{{body{{padding:15px;background:white}}h2{{break-after:avoid}}tr{{break-inside:avoid}}.stats{{gap:30px}}}}
</style></head><body><div class="eyebrow">ANTILLIA / APPLIED INTELLIGENCE / REPRODUCIBLE EXPERIMENT</div><h1>{title}</h1><p class="lede">English benchmark, transparent evaluation and a separate Polish diagnostic. Wyniki testowe, porównanie modeli i jawne ograniczenia.</p><div class="stats"><div><b>{score['macro_f1']*100:.1f}%</b><span>TEST MACRO F1 / EN</span></div><div><b>{r['split_counts']['test']:,}</b><span>HELD-OUT EXAMPLES</span></div><div><b>{r['single_embedding_inference_ms']:.0f} ms</b><span>SINGLE EMBEDDING INFERENCE / CPU</span></div></div>
<h2>01 / Experiment design · Metodyka</h2><p>Frozen multilingual MiniLM encoder with trained MLP; baseline TF-IDF logistic regression. CPU, 2 threads, seed 42. Normalized exact duplicates removed before partitioning. Preprocessing fitted only on train. Model and alpha selected by validation macro F1. Test is reserved for final evaluation.</p><p>Train {r['split_counts']['train']:,} · Validation {r['split_counts']['validation']:,} · Test {r['split_counts']['test']:,}. Selected model: <b>{selected}</b>. Human-review threshold: <b>{r['threshold']:.3f}</b>, selected solely on validation to target 95% selective accuracy with at least 15% coverage; otherwise best selective accuracy at that coverage.</p>
<h2>02 / Held-out performance · Wyniki testowe</h2><svg viewBox="0 0 660 190" role="img" aria-label="Test macro F1 model comparison">{bars}</svg><table><thead><tr><th>Model</th><th>Accuracy</th><th>Macro F1</th><th>{'PR-AUC' if sentiment else 'Top-3 accuracy'}</th></tr></thead><tbody>{modelrows}</tbody></table>
<h2>03 / Polish diagnostic · Polski zestaw kontrolny</h2><p class="note">{r['polish_control']['n']} author-written examples. Small, non-representative diagnostic; not an official benchmark, not used for model selection. Mały autorski zestaw diagnostyczny, nie niezależny benchmark.</p><table><tr><th>Model</th><th>Accuracy</th><th>Macro F1</th></tr>{polish}</table>{domain}
<h2>05 / Confusion matrix · Macierz pomyłek</h2><p>Rows: true label. Columns: predicted label. Hover a cell for exact counts. Class order follows the table below.</p><svg class="matrix" viewBox="0 0 500 500" role="img" aria-label="Full confusion matrix, true labels by predicted labels">{cells}</svg><details open><summary>Per-class precision, recall, F1 and support</summary><table><tr><th>Class</th><th>Precision</th><th>Recall</th><th>F1</th><th>Support</th></tr>{perclass}</table></details>
<h2>06 / Real errors · Rzeczywiste błędy</h2><table><tr><th>Text</th><th>Expected</th><th>Predicted</th></tr>{errors}</table>
<h2>07 / Limits & reproducibility · Ograniczenia</h2><p>Scores are uncalibrated classifier estimates. No reliable out-of-domain detection. Polish transfer is not proven beyond the tiny diagnostic. Pretraining-data overlap cannot be ruled out. {'Binary sentiment only; no neutral class; sarcasm and mixed sentiment are not reliably handled.' if sentiment else '77 banking-specific intents only; not a general support classifier.'} These are project-owned measurements, not external certification.</p><p>MLP optimizer may reach its 160-epoch cap; the actual iteration count is recorded below. Results are retained even when a neural model does not outperform baseline. Run evaluate.ps1 to reproduce metrics using saved artifacts. Checksums, split manifest, model weights and JSON/CSV results are shipped with the project.</p><pre>{e(json.dumps(training,indent=2))}</pre><footer>Antillia · Local CPU experiment · Sources and attribution: LICENSES.md · Machine-readable details: metrics.json / metrics.csv</footer></body></html>'''
 (root/'reports/report.html').write_text(doc,encoding='utf-8')
if __name__=='__main__': render(Path(__file__).resolve().parents[1])
